    'about.hero.title': 'About Horaios Baptist Church',
    'about.hero.subtitle': 'Our Calling & Heritage',
    'about.hero.desc': '"Get up and Walk in the name of Jesus" (Acts 3:2) — Discovering our heritage, our biblical foundation, and our calling as an instrument of God’s Kingdom in Cambodia.',
    'about.journey.badge': 'Our Journey of Faith',
    'about.journey.title': 'Get Up and Walk in the Name of Jesus',
    'about.journey.p1': 'Horaios Baptist Church Cambodia (HBCC) was founded on October 25, 2015, born out of prayer, cross-cultural missionary dedication, and a deep compassion for the people of Cambodia.',
    'about.journey.p2': 'The church\'s beginnings were initiated by Rev. J. Lalduhawma, an Indian missionary sent from the Baptist Church of Mizoram who arrived in Phnom Penh on December 12, 2013. In October 2015, a dormitory ministry was launched to provide housing, mentorship, and education to students. A few days later, regular worship began in the dormitory\'s small hall—gathering Rev. Lalduhawma and his family, the Chinthan family (dormitory warden), seven student residents (two Christian and five non-Christian), and fellow Mizo missionaries.',
    'about.journey.p3': 'The word "Horaios" is originated from a Greek word, \'Horaios\' which simply in English means "Beautiful (Holy)". Its deeper biblical foundation comes from Acts 3:2, at the Beautiful (Horaios) Gate of the temple where the Apostle Peter ministered healing to the lame man in the name of Jesus Christ. Horaios Baptist Church bears its name having faith that the people who are spiritually, physically, and economically weak and unable to walk by themselves may get up and walk in the name of Jesus.',
    'about.journey.address': 'House No. 9L, Street 3BT Chamreun Phal-1, Sangkat Boeung Tompun, Khan Meanchey, Phnom Penh, Cambodia',
