    'about.hero.title': 'អំពី ព្រះវិហារហូរ៉ាអូសបាប់ទីស្ទ',
    'about.hero.subtitle': 'ការត្រាស់ហៅ និងប្រវត្តិរបស់យើង',
    'about.hero.desc': '"ចូរក្រោកឡើង ហើយដើរទៅ ដោយនូវព្រះនាមព្រះយេស៊ូវ" (កិច្ចការ ៣:២) — ស្វែងយល់អំពីប្រវត្តិរបស់យើង មូលដ្ឋានគ្រឹះនៃព្រះគម្ពីរ និងការត្រាស់ហៅរបស់យើងជាឧបករណ៍នៃនគរព្រះនៅកម្ពុជា។',
    'about.journey.badge': 'ដំណើរនៃជំនឿរបស់យើង',
    'about.journey.title': 'ចូរក្រោកឡើង ហើយដើរទៅ ដោយនូវព្រះនាមព្រះយេស៊ូវ',
    'about.journey.p1': 'ព្រះវិហារហូរ៉ាអូសបាប់ទីស្ទ កម្ពុជា (HBCC) ត្រូវបានបង្កើតឡើងនៅថ្ងៃទី ២៥ ខែតុលា ឆ្នាំ ២០១៥ ដែលកើតចេញពីការអធិស្ឋាន ការលះបង់របស់បេសកជន និងសេចក្តីអាណិតស្រឡាញ់យ៉ាងជ្រាលជ្រៅចំពោះប្រជាជនកម្ពុជា។',
    'about.journey.p2': 'ការចាប់ផ្តើមរបស់ព្រះវិហារ ត្រូវបានផ្ដួចផ្ដើមឡើងដោយលោកគ្រូគង្វាល J. Lalduhawma ដែលជាបេសកជនជនជាតិឥណ្ឌា មកពីសាសនាចក្របាទីស្ទ មីហ្សូរ៉ាម (Baptist Church of Mizoram) ហើយបានមកដល់ភ្នំពេញនៅថ្ងៃទី ១២ ខែធ្នូ ឆ្នាំ ២០១៣។ នៅខែតុលា ឆ្នាំ ២០១៥ កិច្ចការបម្រើតាមរយៈអន្តេវាសិកដ្ឋាននិស្សិតត្រូវបានបង្កើតឡើងដើម្បីផ្តល់កន្លែងស្នាក់នៅ ការណែនាំ និងការអប់រំដល់សិស្សនិស្សិត។ ពីរបីថ្ងៃក្រោយមក ការថ្វាយបង្គំជាទៀងទាត់បានចាប់ផ្តើមនៅក្នុងសាលតូចនៃអន្តេវាសិកដ្ឋាន ដោយមានវត្តមានលោកគ្រូ Lalduhawma និងក្រុមគ្រួសារ ក្រុមគ្រួសារលោក Chinthan (អ្នកគ្រប់គ្រងអន្តេវាសិកដ្ឋាន) និស្សិតស្នាក់នៅ ៧ នាក់ (២ នាក់ជាគ្រីស្ទបរិស័ទ និង ៥ នាក់មិនទាន់ជឿ) ព្រមទាំងបេសកជនមីហ្សូមួយចំនួនទៀត។',
    'about.journey.p3': 'ពាក្យ "ហូរ៉ាអូស" (Horaios) មានប្រភពមកពីពាក្យក្រិក ដែលមានន័យសាមញ្ញថា "ល្អឆើត (បរិសុទ្ធ)"។ អត្ថន័យខាងព្រលឹងវិញ្ញាណកាន់តែជ្រាលជ្រៅគឺដកស្រង់ចេញពី គម្ពីរកិច្ចការ ៣:២ នៅមាត់ទ្វារព្រះវិហារដែលហៅថា "ទ្វារល្អឆើត" (Horaios Gate) ជាកន្លែងដែលសាវ័កពេត្រុសបានប្រោសមនុស្សខ្វិនឱ្យជា ដោយនូវព្រះនាមព្រះយេស៊ូវគ្រីស្ទ។ ព្រះវិហារហូរ៉ាអូសបាប់ទីស្ទ យកឈ្មោះនេះដោយមានជំនឿថា អស់អ្នកដែលទន់ខ្សោយខាងវិញ្ញាណ ខាងរូបកាយ ឬខាងសេដ្ឋកិច្ច ហើយមិនអាចដើរដោយខ្លួនឯងបាន នឹងអាចក្រោកឡើងហើយដើរទៅបានដោយនូវព្រះនាមព្រះយេស៊ូវ។',
    'about.journey.address': 'ផ្ទះលេខ 9L ផ្លូវ 3BT ចំរើនផល១ សង្កាត់បឹងទំពុន ខណ្ឌមានជ័យ រាជធានីភ្នំពេញ ប្រទេសកម្ពុជា',
