    'about.doctrine.god_desc': 'ព្រះពិតតែមួយអង្គ គង់នៅអស់កល្បជានិច្ចក្នុងបីអង្គដាច់ដោយឡែកពីគ្នា: ព្រះវរបិតា ព្រះរាជបុត្រា និងព្រះវិញ្ញាណបរិសុទ្ធ — ស្មើគ្នាក្នុងព្រះចេស្ដា និងសិរីល្អ ជាព្រះអាទិករនៃផ្ទៃមេឃ និងផែនដី។',
