    'about.mission.desc': '"ព្រះវិហារហូរ៉ាអូសបាប់ទីស្ទ កម្ពុជា ប្រកាសបេសកកម្មរបស់ខ្លួនតាមរយៈការបង្កើតឡើង ដើម្បីធ្វើជាសញ្ញា ជានិមិត្តរូប និងជាឧបករណ៍នៃនគរព្រះ។ ហើយខិតខំប្រឹងប្រែងដើម្បីការបង្កើតឡើងយ៉ាងរឹងមាំ ការសម្រេចបាន និងការពង្រីកនគរព្រះ ជាទីកន្លែងដែលព្រះគ្រងរាជ្យ ព្រះហឫទ័យរបស់ទ្រង់ត្រូវបានសម្រេច និងព្រះនាមរបស់ទ្រង់ត្រូវបានសរសើរតម្កើង។"',
